-- aar/w3/aar_row_637_draft1.sql. DRAFT 1 by W3 (session_01H1X3ANsGiMnhnbkfphocmo) for the coordinator (seat 36). NOT RUN by W3.
-- One ask_aar_snapshots row for ASK 637 (the agreement step asks only seats that can sit in this debate) and its ask_aar_builders row.
-- Every value is from Wall 12029, 12030, 12034, 12035, 12040 and 12041 (read whole by W3), ask637/w4/plan637.md rev 0 (read whole), the card as stored in W4's thread (read by W3), and md5sum by W3 of the files named.
-- NOT READ by W3: audit_log row 42181; the live Accept Build and Init Seats code; n8n; W1's grade files in git.
-- objective_met is 'in part': written and read back; no run since the write.
-- After the insert: SELECT * FROM ask_aar_snapshots_check(); SELECT * FROM ask_aar_grades_check();
-- The session line below must be the coordinator's own session; written_by is read from it.
BEGIN;
SET LOCAL truth.session_id = '<COORDINATOR SESSION, registered to seat 36>';
WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (637, '0', $t$ASK 637: the agreement step asks only seats that can sit in this debate$t$,
  $t$Accept Build sent the posture to every seat of the judge order except the two debaters' own seats and qwen. Init Seats then drops every seat of a debater's family (unless both debaters are anthropic) and every seat that runs a debater's model (ASK 601). Those seats were asked and paid for and could never sit: in run 42528 (hydrogen, google, against spark, meta) gemini, argon and neon were asked, $0.0831 in all, and all three were dropped for "family google debates in this debate". Change, in Accept Build only: it skips a seat when Init Seats would drop it for family or for the same model, by the same tests, read from the Accept Models rows. Expected effect: those seats are not asked; who sits does not change. Not changed: the prompt; Accept Check, Accept Return, Accept Final; Init Seats. (plan rev 0, heading 1, ask637/w4/plan637.md md5 6b4b95bf)$t$,
  'in part',
  $t$Written by W4 on the operator's press "Write it" at 06:34 CST 2026-11-25 on W4's card (Wall 12040; audit 42181 by W4's post), engine ccaf4660 to ee4e389d, and read back PASS by W1 (Wall 12041: live ee4e389d active, 423 nodes, node-equal to the target 4aea7be6, connections equal, only Accept Build differs from ccaf4660, t637 588 pass 0 fail on the live engine, standing set 31 PASS 0 FAIL). One line of Accept Build changed (the seats filter; the node went from 3,096 to 4,092 characters); the child aad0ad9c is unchanged. IN PART, because no run has been made since the write. Offline (W4's build b1, rebuilt by W1 from its own fetch, Wall 12035): on 132 debater pairings the new asked set is the old set minus the seats Init Seats drops for family or same model (298 cuts in all), and Init Seats gives equal panel_order, panel_reserve, alt_order and single_judge under both with every asked seat ACCEPT; on the 42528 pairing gemini, argon and neon are not asked and sonnet still is; claude against opus cuts only sonnet (same model as claude_synthesis); grok against glm changes nothing; the engine-to-seat map equals Init Seats' for every engine. W1's N1 on the plan (Init Seats reads family from a constant, the new filter from the Accept Models rows) is settled: a row with no family or model is not filtered, and a seat with no active row makes Accept Build fail closed under the old code and the new. W4 corrected its own Wall 12016: sonnet can sit in the 42528 pairing, so the effect there is 3 calls, not 4. One difference noted by W4: with every seat ACCEPT the replay seats sonnet as reserve where the live 42528 row reads reserve none, because the live statuses differed; old and new are equal either way. NOT SEARCHED by W4: Replay Rows' accept_probe mode; the dashboard's AGREEMENT display. NOT CHECKED by W1: whether the fixture still equals the live model_config rows and judge order. Open: two clean live runs.$t$,
  '12029, 12030, 12034, 12035, 12040, 12041',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$W4's write card (cmsg_017ZQamDMHrS6fqMHnQDVo586jGdfdRJ3wFNt7b3RdDsiE, "Write ASK 637 (judges who cannot sit are not asked to agree)?"): he pressed "Write it" at 06:34 CST 2026-11-25 (press time from Wall 12040). W3 read the card's question and options in W4's thread; W3 did not read the press itself. There was no build card: the build was offline files only, and the card came after the build grade.$t$::text),
  $j${"answer": "Write it", "question": "Write ASK 637 (judges who cannot sit are not asked to agree)?", "options": {"Write it": "W4 changes Accept Build on the live engine so it skips seats Init Seats bars for family or model; fetch back, audit row, W1 readback.", "Hold": "Nothing is written; the agreement step keeps asking and paying for seats that can never sit."}, "thread": "W4", "card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo586jGdfdRJ3wFNt7b3RdDsiE", "press_time": "06:34 CST 2026-11-25", "source": "the card as stored in W4's thread, read by W3; press time from Wall 12040."}$j$::jsonb,
  'W4',
  $j${"md5": "6b4b95bf2b76f83c3979b0a11ab226c8", "path": "ask637/w4/plan637.md", "note": "plan rev 0, graded PASS WITH N1 by W1 (Wall 12030); N1 was settled in the build (Wall 12034, 12035).", "source": "md5sum by W3; Wall 12030"}$j$::jsonb,
  $j$[{"path": "ask637/w4/b1/b637.cjs", "md5": "8afa80340a39a88770537a1dd8653a82", "what": "build script"}, {"path": "ask637/w4/b1/tg/target_engine_637.json", "md5": "4aea7be6b71b02fc9d597923be103554", "what": "target engine"}, {"path": "ask637/w4/b1/t637.cjs", "md5": "80d937f0188c2f5f5c4bf257b2e454bb", "what": "test"}, {"path": "ask637/w4/b1/out_t637.txt", "md5": "75f76a8bfd0e976d5b7eee9199542cc8", "what": "test output"}, {"path": "ask637/w4/b1/fx/seats_fx.json", "md5": "b8a8eb3c94b623c3ca8c2b58f1bdae1e", "what": "fixture: the active model_config_jfl rows (24) and judge order v6"}, {"path": "ask637/w4/write/write637.sh", "md5": "2ca0769988d7091dbdc07a89fcc96fa0", "what": "write script"}, {"path": "ask637/w4/write/write637_run.txt", "md5": "5a4ef5cc34ae7d0fe322a492c3bc2bc6", "what": "write script output"}, {"path": "ask637/w4/write/fetchback_eng_637.json", "md5": "0c648eac6ff5800bf248e920e839b185", "what": "fetch-back after the write"}]$j$::jsonb,
  $j${"engine": "ask637/w4/write/revert_eng_637.json, md5 f7225fb5b44487f256c7692d3d0e7e5a (restores ccaf4660)", "child": "not written; nothing to revert", "database": "not written; nothing to revert", "rehearsed": "not stated in the posts W3 read", "source": "Wall 12040; md5sum by W3"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS WITH N1 (plan rev 0)", "wall_id": 12030, "md5_graded": "6b4b95bf", "verdict_norm": "PASS", "source": "Wall 12030"}, {"seat": "W1", "verdict": "PASS (build b1)", "wall_id": 12035, "md5_graded": "4aea7be6b71b02fc9d597923be103554", "verdict_norm": "PASS", "source": "Wall 12035"}]$j$::jsonb,
  ARRAY['4aea7be6b71b02fc9d597923be103554'], '[42181]'::jsonb,
  $j$[{"kind": "n8n workflow", "name": "ORACLE_DEBATE_V1 moMxiV4Irg1uRBZN, node Accept Build", "before": "version ccaf4660; seats = the judge order less the debaters' seats and qwen", "after": "version ee4e389d; the filter also drops a seat whose Accept Models family equals a debater's family (unless both debaters are anthropic) or whose normalised api_model equals a debater's model; tagged ASK 637. 423 nodes, connections equal."}]$j$::jsonb,
  $j$[{"name": "t637.cjs on the build", "result": "588 pass, 0 fail: C1 132 pairings (asked set and equal seating); the 42528 pairing; C2 claude against opus, grok against glm; N1 seats with no family; C3 engine-to-seat map; C4 only Accept Build differs; C5 one ASK 637 tag, no new catch", "source": "Wall 12034; rebuilt and rerun by W1, Wall 12035"}, {"name": "Standing set with child aad0ad9c", "result": "31 PASS, 0 FAIL on the target (W4, W1), on the fetch-back (W4, Wall 12040) and on live (W1, Wall 12041); pair check PASSES", "source": "Wall 12034, 12035, 12040, 12041"}, {"name": "NOT RUN", "result": "any live call; the plan needs none (the replay is the test)", "source": "plan637.md heading 6"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "PASS (live ee4e389d, active, 423 nodes, node-equal to target 4aea7be6, connections equal; only Accept Build differs from ccaf4660; t637 588 pass 0 fail on live; standing 31 PASS 0 FAIL)", "wall_id": 12041, "source": "Wall 12041 (commit 0e85d070)"}]$j$::jsonb,
  $j${"case": "NO RUN YET.", "runs": [], "mark_for_the_next_run": "on the first live run whose debaters' family has a judge seat in the order: no AGREEMENT line and no Accept Call cost for those seats, and the row's seating equals what the old engine would seat.", "not_shown": "the filter on a live run.", "source": "plan637.md heading 6; Wall 12040"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "NOT WRITTEN. Drafted by W3: two pairs on part 08.0 (version 320, 52,600 characters), file manual1123/w3/a637/em_pairs_637_draft1.json; preview 53,910 characters, md5 0a7b2cbfc07d6cd7321b37e4dcd7b783, would be version 325; the AGREEMENT bullet's list of seats asked is changed and one sub-bullet of 1,220 characters is added. It waits on W1's grade and the operator's card; a draft 2 of this row follows the write."}$j$::jsonb,
  'read back', $j$[12029, 12030, 12034, 12035, 12040, 12041]$j$::jsonb)
RETURNING id)
INSERT INTO ask_aar_builders (snapshot_id, builder_seats, sources, written_by)
SELECT s.id, ARRAY['W4'], $j$[{"seat": "W4", "what": "planned, built (build b1) and wrote ASK 637 on the operator's card", "wall_id": 12040}]$j$::jsonb, current_setting('truth.session_id') FROM s;
SELECT * FROM ask_aar_snapshots_check() WHERE row_id = (SELECT max(id) FROM ask_aar_snapshots);
SELECT * FROM ask_aar_grades_check() WHERE snapshot_id = (SELECT max(id) FROM ask_aar_snapshots);
COMMIT;
